exercises.solutionCode:
import json

def execute_tool_call(tool_call, session):
    args = json.loads(tool_call.function.arguments)
    if tool_call.function.name == "cancel_subscription":
        if args.get("user_id") != session.authenticated_user_id:
            raise PermissionError("Tool call targets a user outside the current session.")
        return cancel_subscription(session.authenticated_user_id)
    raise ValueError(f"Unknown tool: {tool_call.function.name}")

examples.code:
def run_agent(user_text, client, tools, tool_functions, max_iterations=8):
    messages = [{"role": "user", "content": user_text}]
    for step in range(max_iterations):
        response = client.chat.completions.create(model="gpt-4.1", messages=messages, tools=tools)
        message = response.choices[0].message
        messages.append(message)
        if not message.tool_calls:
            return {"status": "done", "answer": message.content, "steps_used": step + 1}
        for tool_call in message.tool_calls:
            args = json.loads(tool_call.function.arguments)
            result = tool_functions[tool_call.function.name](**args)
            messages.append({"role": "tool", "tool_call_id": tool_call.id, "content": json.dumps(result)})
    return {"status": "max_iterations_reached", "answer": None, "steps_used": max_iterations}

DESTRUCTIVE_TOOLS = {"delete_resource", "send_refund", "cancel_subscription"}

def execute_with_guardrails(tool_call, tool_functions, request_human_approval):
    args = json.loads(tool_call.function.arguments)
    name = tool_call.function.name
    if name in DESTRUCTIVE_TOOLS:
        approved = request_human_approval(name, args)   # blocks until a human confirms
        if not approved:
            return {"executed": False, "reason": "Rejected by human reviewer."}
    result = tool_functions[name](**args)
    return {"executed": True, "result": result}

